namespace fs = std::filesystem;

namespace pxe {
namespace {

// Marker lines. Everything between them is owned by the server and rewritten
// on every refresh; the rest of the menu file is never touched.
constexpr const char* kMenuBegin = ">>> ISOS (generated";
constexpr const char* kMenuEnd = "<<< ISOS <<<";

constexpr const char* kMenuHeader =
    "# >>> ISOS (generated by pxesrv - do not edit, rewritten automatically) >>>";
constexpr const char* kMenuFooter = "# <<< ISOS <<<";

// boot.ipxe needs two regions: the menu items and the labels they jump to.
constexpr const char* kIpxeItemsBegin = ">>> ISOS-MENU (generated";
constexpr const char* kIpxeItemsEnd = "<<< ISOS-MENU <<<";
constexpr const char* kIpxeItemsHeader =
    "# >>> ISOS-MENU (generated by pxesrv - do not edit, rewritten automatically) >>>";
constexpr const char* kIpxeItemsFooter = "# <<< ISOS-MENU <<<";

constexpr const char* kIpxeActionsBegin = ">>> ISOS-ACTIONS (generated";
constexpr const char* kIpxeActionsEnd = "<<< ISOS-ACTIONS <<<";
constexpr const char* kIpxeActionsHeader =
    "# >>> ISOS-ACTIONS (generated by pxesrv - do not edit, rewritten automatically) >>>";
constexpr const char* kIpxeActionsFooter = "# <<< ISOS-ACTIONS <<<";

std::string toLower(std::string value) {
    std::transform(value.begin(), value.end(), value.begin(),
                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    return value;
}

bool hasIsoExtension(const std::string& name) {
    if (name.size() <= 4) return false;
    return toLower(name.substr(name.size() - 4)) == ".iso";
}

/*
 * Heuristic: Windows install/live images do not contain a Linux kernel that
 * Debian-style loopback boot can use, so the GRUB entry must chainload the
 * EFI boot manager from inside the ISO instead.
 */
bool isWindowsIso(const std::string& name) {
    const std::string lower = toLower(name);
    return lower.find("windows") != std::string::npos ||
           lower.find("winpe") != std::string::npos ||
           lower.find("win10") != std::string::npos ||
           lower.find("win11") != std::string::npos ||
           lower.find("win7") != std::string::npos ||
           lower.find("win8") != std::string::npos ||
           lower.find("win_") != std::string::npos ||
           lower.find("win-") != std::string::npos ||
           lower.find("win ") != std::string::npos ||
           lower.find("hiren") != std::string::npos ||
           (lower.rfind("win", 0) == 0);  // starts with "win"
}

// A name that can be used as an unquoted GRUB/PXELINUX path and as a menu
// label. Anything else (quotes, newlines) would break the generated script.
bool isSafeName(const std::string& name) {
    if (name.empty()) return false;
    for (char c : name) {
        if (c == '"' || c == '\'' || c == '\n' || c == '\r' || c == '\\') return false;
    }
    return true;
}

std::vector<std::string> scanIsos(const fs::path& dir) {
    std::vector<std::string> out;
    std::error_code ec;
    if (!fs::is_directory(dir, ec)) return out;

    fs::directory_iterator it(dir, ec);
    const fs::directory_iterator end;
    for (; !ec && it != end; it.increment(ec)) {
        std::error_code fileEc;
        if (!it->is_regular_file(fileEc)) continue;
        const std::string name = it->path().filename().string();
        if (!hasIsoExtension(name)) continue;
        if (!isSafeName(name)) {
            Logger::instance().warn("ISO menu: skipping unsupported file name: " + name);
            continue;
        }
        out.push_back(name);
    }
    if (ec) {
        Logger::instance().warn("ISO menu: cannot read " + dir.string() + ": " + ec.message());
    }
    std::sort(out.begin(), out.end());
    return out;
}

std::string grubBlock(const std::vector<std::string>& isos) {
    std::ostringstream out;
    out << kMenuHeader << "\n";

    if (isos.empty()) {
        out << "menuentry \"(No ISO images in /isos)\" --class info {\n"
            << "    echo \"Place .iso files in /isos and reboot to see them here.\"\n"
            << "    sleep 3\n"
            << "}\n";
    }

    for (const std::string& name : isos) {
        const std::string path = "/isos/" + name;
        if (isWindowsIso(name)) {
            /*
             * Windows/PE ISOs do not carry a Linux kernel. Under UEFI we can
             * chainload the EFI boot manager from inside the ISO. GRUB serves
             * the ISO file over its net (TFTP) device; loopback reads it as a
             * file, which is slower than a local disk but works for Live/PE
             * media.
             */
            out << "menuentry \"Windows ISO: " << name << "\" --class windows {\n"
                << "    insmod loopback\n"
                << "    insmod part_gpt\n"
                << "    insmod part_msdos\n"
                << "    insmod fat\n"
                << "    insmod ntfs\n"
                << "    insmod chain\n"
                << "    echo \"Booting " << name << " (UEFI chainload) ...\"\n"
                << "    loopback loop \"" << path << "\"\n"
                << "    chainloader (loop)/efi/boot/bootx64.efi\n"
                << "    boot\n"
                << "    chainloader (loop)/efi/microsoft/boot/bootmgfw.efi\n"
                << "    boot\n"
                << "    echo \"No EFI boot manager found in " << name << ".\"\n"
                << "    sleep 5\n"
                << "}\n";
        } else {
            /*
             * Debian/Ubuntu/Mint-style live/install layout. Other distributions
             * may need a custom menuentry (add it outside the ISOS markers).
             */
            out << "menuentry \"ISO: " << name << "\" --class iso {\n"
                << "    insmod loopback\n"
                << "    insmod linux\n"
                << "    echo \"Booting " << name << " (loopback) ...\"\n"
                << "    loopback loop \"" << path << "\"\n"
                << "    linux  (loop)/boot/vmlinuz iso-scan/filename=\"" << path << "\" quiet\n"
                << "    initrd (loop)/boot/initrd.img\n"
                << "}\n";
        }
    }

    out << kMenuFooter << "\n";
    return out.str();
}

/*
 * iPXE menus cannot quote a URL, so an ISO whose name contains a space stays
 * out of the menu instead of producing an entry that fails at boot time.
 */
bool ipxeUsable(const std::string& name) { return name.find(' ') == std::string::npos; }

std::string ipxeItemsBlock(const std::vector<std::string>& isos) {
    std::ostringstream out;
    out << kIpxeItemsHeader << "\n";

    int index = 0;
    for (const std::string& name : isos) {
        if (!ipxeUsable(name)) continue;
        if (index == 0) {
            out << "item --gap --            --- ISO Images ---\n";
        }
        out << "item iso_" << ++index << "               " << name << "\n";
    }
    if (index == 0) {
        out << "# No ISO images in /isos.\n";
    }

    out << kIpxeItemsFooter << "\n";
    return out.str();
}

std::string ipxeActionsBlock(const std::vector<std::string>& isos) {
    std::ostringstream out;
    out << kIpxeActionsHeader << "\n";

    int index = 0;
    for (const std::string& name : isos) {
        if (!ipxeUsable(name)) continue;
        ++index;
        out << ":iso_" << index << "\n";
        if (isWindowsIso(name)) {
            /*
             * Windows/PE images need INT13 drive mapping so the Windows boot
             * manager can read its files from the virtual CD. --no-describe
             * avoids a broken EDD entry some BIOSes choke on.
             */
            out << "echo Booting " << name << " over HTTP (Windows sanboot)...\n"
                << "sanboot --no-describe --drive 0x80 ${boot_url}/isos/" << name << " ||\n"
                << "sanboot --no-describe ${boot_url}/isos/" << name << " ||\n"
                << "sanboot ${boot_url}/isos/" << name << " || goto failed\n";
        } else {
            out << "echo Booting " << name << " over HTTP (sanboot)...\n"
                << "sanboot ${boot_url}/isos/" << name << " || goto failed\n";
        }
    }
    if (index == 0) {
        out << "# No ISO images in /isos.\n";
    }

    out << kIpxeActionsFooter << "\n";
    return out.str();
}

// Replaces the marked block (markers included) with `block`, keeping the rest
// of the file byte-for-byte. Returns the original text when no markers exist.
std::string replaceRegion(const std::string& content, const std::string& block,
                          const std::string& beginTag, const std::string& endTag) {
    const size_t beginMarker = content.find(beginTag);
    if (beginMarker == std::string::npos) return content;

    const size_t previousNewline = content.rfind('\n', beginMarker);
    const size_t begin = (previousNewline == std::string::npos) ? 0 : previousNewline + 1;

    const size_t endMarker = content.find(endTag, beginMarker);
    if (endMarker == std::string::npos) return content;

    size_t end = content.find('\n', endMarker);
    end = (end == std::string::npos) ? content.size() : end + 1;

    return content.substr(0, begin) + block + content.substr(end);
}

std::string readFile(const fs::path& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in.is_open()) return std::string();
    std::ostringstream buffer;
    buffer << in.rdbuf();
    return buffer.str();
}

bool writeFile(const fs::path& path, const std::string& data) {
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    if (!out.is_open()) return false;
    out.write(data.data(), static_cast<std::streamsize>(data.size()));
    return out.good();
}

enum class MenuStyle { Grub, IpXe };

bool classify(const fs::path& path, MenuStyle& style) {
    const std::string name = path.filename().string();
    if (name == "grub.cfg") {
        style = MenuStyle::Grub;
        return true;
    }
    if (name == "boot.ipxe") {
        style = MenuStyle::IpXe;
        return true;
    }
    return false;
}

} // namespace

int IsoMenu::refresh(const Config& cfg) {
    const fs::path bootRoot(cfg.boot_root);
    std::error_code ec;
    if (!fs::is_directory(bootRoot, ec)) {
        Logger::instance().warn("ISO menu: boot root is not a directory: " + bootRoot.string());
        return -1;
    }

    const std::vector<std::string> isos = scanIsos(bootRoot / "isos");

    const std::string grub = grubBlock(isos);
    const std::string ipxeItems = ipxeItemsBlock(isos);
    const std::string ipxeActions = ipxeActionsBlock(isos);

    int rewritten = 0;
    fs::recursive_directory_iterator it(bootRoot, ec);
    const fs::recursive_directory_iterator end;
    for (; !ec && it != end; it.increment(ec)) {
        std::error_code fileEc;
        if (!it->is_regular_file(fileEc)) continue;

        MenuStyle style;
        if (!classify(it->path(), style)) continue;

        const std::string content = readFile(it->path());
        if (content.empty()) continue;

        std::string updated = content;
        switch (style) {
            case MenuStyle::Grub:
                updated = replaceRegion(updated, grub, kMenuBegin, kMenuEnd);
                break;
            case MenuStyle::IpXe:
                updated = replaceRegion(updated, ipxeItems, kIpxeItemsBegin, kIpxeItemsEnd);
                updated = replaceRegion(updated, ipxeActions, kIpxeActionsBegin, kIpxeActionsEnd);
                break;
        }
        if (updated == content) continue;

        if (!writeFile(it->path(), updated)) {
            Logger::instance().warn("ISO menu: cannot write " + it->path().string());
            continue;
        }
        ++rewritten;
    }

    if (rewritten > 0) {
        Logger::instance().info("ISO menu updated: " + std::to_string(isos.size()) +
                                " ISO image(s), " + std::to_string(rewritten) +
                                " menu file(s) rewritten");
    }
    return static_cast<int>(isos.size());
}

} // namespace pxe
